/usr/bin/bash -lc "cat > /tmp/qprofile.pl <<'PL'
use strict; use warnings;
my (@sum,@n); my "'$state=0; my $seq='"''; my "'$qual='"''; my "'$count=0; my $max=50000;
while (<>) {
  chomp;
  if ($state==0) { $state=1; next; }
  elsif ($state==1) { $seq=$_; $state=2; next; }
  elsif ($state==2) { $state=3; next; }
  else {
    $qual=$_;
    my $len=length($qual); $len=length($seq) if length($seq)<$len;
    for my $i (0..$len-1) {
      my $q=ord(substr($qual,$i,1))-33;
      $sum[$i]+=$q; $n[$i]++;
    }
    $count++;
    last if $count>=$max;
    $state=0;
  }
}
for my $i (0..$#sum) { print join("'"\\t\", "'$i+1, $sum[$i]/$n[$i])."'"\\n\"; }
PL
for kind in forward reverse; do
  f=data/inputs/paired_input_data/mfmt_cecal_1191_2/"'$kind/$kind.fastqsanger.gz
  echo "=== $kind"
  zcat "$f" | perl /tmp/qprofile.pl | awk '"'NR%10==1 || NR==250 {print}' | head -30
done"

